# jq Interpreter

This project provides a standalone Python implementation boundary for jq. The executable
`./jq -c '<program>'` reads one JSON value per line from standard input and emits each
result as compact JSON on its own output line.

Compile errors exit with status `3`; runtime errors exit with status `5`; successful
evaluation exits with status `0`. The supplied conformance command is:

```sh
sh sources/full_test.sh
```

The implementation uses only Python's standard library and does not invoke another jq.

"""Process boundary for the standalone jq executable."""

from __future__ import annotations

import argparse
import json
import sys
from collections.abc import Sequence
from typing import Any

from jq_parser import ParseError, parse
from jq_runtime import RuntimeFailure, evaluate


def _arguments(arguments: Sequence[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(prog="jq")
    parser.add_argument("-c", dest="program", required=True)
    return parser.parse_args(arguments)


def main(arguments: Sequence[str] | None = None) -> int:
    """Run jq's compact stdin/stdout protocol and return its process status."""
    try:
        options = _arguments(sys.argv[1:] if arguments is None else arguments)
        program = parse(options.program)
    except (ParseError, ValueError, SystemExit) as error:
        if isinstance(error, SystemExit):
            return int(error.code or 0)
        print(f"jq: compile error: {error}", file=sys.stderr)
        return 3

    try:
        for line in sys.stdin:
            if not line.strip():
                continue
            value: Any = json.loads(line)
            for result in evaluate(program, value):
                print(json.dumps(result, separators=(",", ":"), ensure_ascii=False))
    except (json.JSONDecodeError, RuntimeFailure, TypeError, ValueError) as error:
        print(f"jq: runtime error: {error}", file=sys.stderr)
        return 5
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"""Generator-based jq evaluation boundary."""


class RuntimeFailure(RuntimeError):
    """Raised after compilation when a filter cannot evaluate its input."""


def _walk(node, value):
    if node.kind == "identity":
        yield value
    elif node.kind == "literal":
        yield node.value
    elif node.kind == "true":
        yield True
    elif node.kind == "false":
        yield False
    elif node.kind == "null":
        yield None
    elif node.kind == "empty":
        return
    elif node.kind == ",":
        yield from _walk(node.children[0], value)
        yield from _walk(node.children[1], value)
    elif node.kind == "|":
        for intermediate in _walk(node.children[0], value):
            yield from _walk(node.children[1], intermediate)
    elif node.kind == "iterate":
        if isinstance(value, list):
            yield from value
        elif isinstance(value, dict):
            yield from value.values()
        else:
            raise RuntimeFailure("cannot iterate over this value")
    else:
        raise RuntimeFailure(f"unknown AST node: {node.kind}")


def evaluate(program, value):
    """Evaluate an AST against one input, preserving ordered generator semantics."""
    yield from _walk(program, value)
"""Parser and immutable AST for the jq language front end.

The parser deliberately keeps evaluation concerns out of the tree.  Every
node records its construct and children, so the generator runtime can choose
how to evaluate it without the parser retaining input or lexical state.
"""

from __future__ import annotations

from dataclasses import dataclass
import json

from jq_lexer import LexError, Token, tokenize


class ParseError(ValueError):
    """Raised for syntax or compile-time jq errors."""


@dataclass(frozen=True)
class Node:
    kind: str
    value: object = None
    children: tuple["Node", ...] = ()

    def __repr__(self) -> str:
        if self.children:
            return f"Node({self.kind!r}, {self.value!r}, {self.children!r})"
        return f"Node({self.kind!r}, {self.value!r})"


_PREC = {",": 10, "//": 20, "=": 30, "|=": 30, "+=": 30, "-=": 30,
         "*=": 30, "/=": 30, "%=": 30, "//=": 30, "or": 40, "and": 50,
         "==": 60, "!=": 60, "<": 60, ">": 60, "<=": 60, ">=": 60,
         "+": 70, "-": 70, "*": 80, "/": 80, "%": 80, "|": 90}
_RIGHT_ASSOC = {"=", "|=", "+=", "-=", "*=", "/=", "%=", "//=", "//", "|"}


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.index = 0
        self.functions: set[tuple[str, int]] = set()
        self.bindings: list[set[str]] = [set()]

    def current(self) -> Token:
        return self.tokens[self.index]

    def take(self) -> Token:
        token = self.current()
        self.index += 1
        return token

    def accept(self, value: str) -> bool:
        if self.current().value == value:
            self.take()
            return True
        return False

    def expect(self, value: str) -> Token:
        if not self.accept(value):
            token = self.current()
            raise ParseError(f"expected {value!r} at position {token.position}")
        return self.tokens[self.index - 1]

    def expect_kind(self, kind: str) -> Token:
        token = self.current()
        if token.kind != kind:
            raise ParseError(f"expected {kind!r} at position {token.position}")
        return self.take()

    def parse(self) -> Node:
        declarations: list[Node] = []
        while self.current().value in {"module", "import", "include", "def"}:
            if self.current().value == "def":
                declarations.append(self.parse_definition())
            else:
                declarations.append(self.parse_module_directive())
        if self.current().kind == "eof":
            raise ParseError("expected filter")
        body = self.expression()
        if self.current().kind != "eof":
            token = self.current()
            raise ParseError(f"unexpected token {token.value!r} at position {token.position}")
        if declarations:
            return Node("program", children=tuple(declarations + [body]))
        return body

    def expression(self, minimum: int = 0) -> Node:
        left = self.term()
        while True:
            token = self.current()
            op = token.value
            if op == "as":
                if minimum > 25:
                    break
                self.take()
                pattern = self.pattern()
                self.expect("|")
                self.bindings[-1].update(self.pattern_names(pattern))
                right = self.expression(0)
                left = Node("as", children=(left, pattern, right))
                continue
            if op not in _PREC or _PREC[op] < minimum:
                break
            self.take()
            next_min = _PREC[op] if op in _RIGHT_ASSOC else _PREC[op] + 1
            right = self.expression(next_min)
            left = Node(op, children=(left, right))
        return left

    def term(self) -> Node:
        token = self.take()
        if token.kind == "eof":
            raise ParseError(f"expected filter at position {token.position}")
        if token.value == ".":
            node = Node("identity")
        elif token.kind == "field":
            node = Node("index", value=token.value, children=(Node("identity"),))
        elif token.kind == "binding":
            if token.value not in self.bindings[-1]:
                # Builtin/private bindings are legal without a local declaration.
                if not token.value.startswith("__") and token.value not in {"ENV", "ARGS"}:
                    raise ParseError(f"undefined variable ${token.value}")
            node = Node("binding", token.value)
        elif token.kind == "number":
            node = Node("literal", json.loads(token.value))
        elif token.kind == "string":
            node = Node("literal", token.value)
        elif token.kind == "qqstring_start":
            node = self.qqstring()
        elif token.value == "if":
            node = self.conditional()
        elif token.value == "try":
            node = self.try_expression()
        elif token.value in {"reduce", "foreach"}:
            node = self.reducer(token.value)
        elif token.value == "label":
            label = self.take()
            if label.kind != "binding":
                raise ParseError("label requires a binding")
            self.expect("|")
            node = Node("label", label.value, (self.expression(),))
        elif token.value == "break":
            label = self.take()
            if label.kind != "binding":
                raise ParseError("break requires a label")
            node = Node("break", label.value)
        elif token.kind in {"word", "format"}:
            node = self.word(token)
        elif token.value == "(" :
            node = self.expression()
            self.expect(")")
        elif token.value == "[":
            node = self.array()
        elif token.value == "{":
            node = self.object()
        elif token.value == "-":
            node = Node("negate", children=(self.term(),))
        elif token.value == "..":
            node = Node("recurse")
        else:
            raise ParseError(f"unexpected token {token.value!r} at position {token.position}")
        return self.postfix(node)

    def word(self, token: Token) -> Node:
        if token.kind == "format":
            base = Node("format", token.value)
            if self.current().kind in {"string", "qqstring_start"}:
                return Node("format_string", children=(base, self.term()))
            return base
        if token.value in {"true", "false", "null", "empty"}:
            return Node(token.value)
        if self.accept("("):
            args = self.arguments()
            return Node("call", token.value, tuple(args))
        return Node("call", token.value, ())

    def postfix(self, node: Node) -> Node:
        while True:
            if self.current().kind == "field":
                field = self.take().value
                optional = self.accept("?")
                node = Node("index_opt" if optional else "index", field, (node,))
            elif self.accept(".") or self.current().kind in {"string", "qqstring_start"}:
                key = self.take()
                if key.kind not in {"string", "qqstring_text"}:
                    raise ParseError(f"expected string field at position {key.position}")
                optional = self.accept("?")
                node = Node("index_opt" if optional else "index", key.value, (node,))
            elif self.accept("["):
                if self.accept("]"):
                    node = Node("iterate", children=(node,))
                else:
                    first = self.expression()
