            else:
                value = Node("index", key.value, (Node("identity"),))
            pairs.append(Node("pair", key.value, (value,)))
            if not self.accept(","):
                break
        self.expect("}")
        return Node("object", children=tuple(pairs))

    def conditional(self) -> Node:
        condition = self.expression()
        self.expect("then")
        yes = self.expression()
        branches = [condition, yes]
